using Microsoft.EntityFrameworkCore;
using Wolfgang.AuditTrail.Schema;

namespace Wolfgang.AuditTrail.EntityFrameworkCore.Schema.Tests.Integration.TestSupport;



/// <summary>
/// Reads and replays the frozen per-provider install scripts embedded under
/// <c>Fixtures/V&lt;version&gt;/</c>.
/// </summary>
/// <remarks>
/// <para>
/// Each script is the exact output of
/// <c>AuditSchemaMigrator.RunAsync(dryRun: true)</c> against a fresh database on
/// that provider, captured while the library installed that schema version. It
/// was generated by the production migrator, not typed, so it carries every
/// facet the model configured at the time: store types, lengths, precision,
/// nullability, constraint and index names, and provider preamble such as
/// Pomelo's <c>ALTER DATABASE CHARACTER SET</c>.
/// </para>
/// <para>
/// <strong>Never regenerate these files.</strong> Once a later schema version
/// ships, a frozen script is the only faithful record of what the earlier
/// version installed, and it is what <see cref="ReplayAsync"/> executes to
/// obtain a genuine version-N database to upgrade. Regenerating it from a newer
/// model would silently turn that test into "upgrade from the current version",
/// which proves nothing.
/// </para>
/// </remarks>
public static class FrozenInstallScripts
{
    /// <summary>
    /// Returns the frozen install script for <paramref name="providerName"/>
    /// (as <see cref="ISchemaProviderFixture.ProviderName"/> spells it) at
    /// schema <paramref name="version"/>, with line endings normalised to
    /// <c>\n</c> so the comparison does not depend on the platform the script
    /// was captured on.
    /// </summary>
    /// <exception cref="InvalidOperationException">If no script is embedded for that provider and version.</exception>
    public static async Task<string> ReadAsync(int version, string providerName)
    {
        var resourceName = $"V{version}.{providerName}.sql";

        await using var stream = typeof(FrozenInstallScripts).Assembly.GetManifestResourceStream(resourceName)
            ?? throw new InvalidOperationException($"No frozen install script is embedded as '{resourceName}'.");

        using var reader = new StreamReader(stream);
        var script = await reader.ReadToEndAsync();

        return NormaliseLineEndings(script);
    }



    /// <summary>
    /// Installs schema <paramref name="version"/> into the empty database behind
    /// <paramref name="context"/> exactly as that version's build would have:
    /// executes the frozen script statement by statement, then stamps the
    /// version row. The result is a genuine version-<paramref name="version"/>
    /// database for the migrator to upgrade.
    /// </summary>
    /// <remarks>
    /// The dry run joins the migrator's commands with <c>";\n\n"</c>, and every
    /// command already ends in <c>;</c>, so a line holding a lone <c>;</c> is
    /// the boundary between two statements. The version row is not part of the
    /// dry run -- the migrator writes it through
    /// <see cref="AuditSchemaVersionStore"/> after the DDL -- so it is stamped
    /// here the same way.
    /// </remarks>
    /// <exception cref="ArgumentNullException">If <paramref name="context"/> is <c>null</c>.</exception>
    public static async Task ReplayAsync(AuditMigrationsDbContext context, int version, string providerName)
    {
        ArgumentNullException.ThrowIfNull(context);

        var script = await ReadAsync(version, providerName);

        foreach (var statement in SplitStatements(script))
        {
#pragma warning disable EF1002 // The SQL is a frozen fixture generated by EF Core's own SQL generator, not user input.
            await context.Database.ExecuteSqlRawAsync(statement);
#pragma warning restore EF1002
        }

        await AuditSchemaVersionStore.UpsertInstalledVersionAsync(context, version, CancellationToken.None);
    }



    /// <summary>
    /// Normalises <c>\r\n</c> to <c>\n</c>. EF Core joins generated DDL with
    /// <see cref="Environment.NewLine"/>, so a script captured on Windows and
    /// one generated on Linux differ only in line endings.
    /// </summary>
    /// <exception cref="ArgumentNullException">If <paramref name="script"/> is <c>null</c>.</exception>
    public static string NormaliseLineEndings(string script)
    {
        ArgumentNullException.ThrowIfNull(script);
        return script.Replace("\r\n", "\n", StringComparison.Ordinal);
    }



    private static IEnumerable<string> SplitStatements(string script)
    {
        return script
            .Split('\n')
            .Aggregate(
                new List<List<string>> { new() },
                (statements, line) =>
                {
                    if (line.Trim() == ";")
                    {
                        statements.Add([]);
                    }
                    else
                    {
                        statements[^1].Add(line);
                    }
                    return statements;
                })
            .Select(lines => string.Join('\n', lines).Trim())
            .Where(statement => statement.Length > 0);
    }
}
